    const path = event.path;
    const httpMethod = event.httpMethod;

    console.log(`Processing request: ${httpMethod} ${path}`);

    if (httpMethod === 'GET' && path.startsWith('/data')) {
        return await getData(event);
    } else if (httpMethod === 'POST' && path === '/data') {
        return await postData(event);
    } else if (httpMethod === 'DELETE' && path === '/data') {
        return await deleteData(event);
    } else if (httpMethod === 'PUT' && path.startsWith('/data/:id')) {
        return await putData(event);
    } else {
        return {
            statusCode: 404,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ error: 'Not Found' })
        };
    }
};

